skip_64_store_event(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData) -> dfp_read_field_def_store_event(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData).

decode_msg_store_instance(Bin, TrUserData) ->
