'd_enum_reckon.gateway.v1.StoreEventType'(0) -> 'STORE_EVENT_TYPE_UNSPECIFIED';
'd_enum_reckon.gateway.v1.StoreEventType'(1) -> 'STORE_EVENT_TYPE_ANNOUNCED';
'd_enum_reckon.gateway.v1.StoreEventType'(2) -> 'STORE_EVENT_TYPE_RETIRED';
'd_enum_reckon.gateway.v1.StoreEventType'(V) -> V.

'd_enum_reckon.gateway.v1.StoreMode'(0) -> 'STORE_MODE_UNSPECIFIED';
'd_enum_reckon.gateway.v1.StoreMode'(1) -> 'STORE_MODE_SINGLE';
'd_enum_reckon.gateway.v1.StoreMode'(2) -> 'STORE_MODE_CLUSTER';
'd_enum_reckon.gateway.v1.StoreMode'(V) -> V.

read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        list_stores_request -> merge_msg_list_stores_request(Prev, New, TrUserData);
        list_stores_response -> merge_msg_list_stores_response(Prev, New, TrUserData);
        get_store_request -> merge_msg_get_store_request(Prev, New, TrUserData);
        get_store_response -> merge_msg_get_store_response(Prev, New, TrUserData);
        watch_stores_request -> merge_msg_watch_stores_request(Prev, New, TrUserData);
        store_event -> merge_msg_store_event(Prev, New, TrUserData);
        store_instance -> merge_msg_store_instance(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_list_stores_request/3}).
merge_msg_list_stores_request(_Prev, New, _TrUserData) -> New.

-compile({nowarn_unused_function,merge_msg_list_stores_response/3}).
merge_msg_list_stores_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{instances := PFinstances}, #{instances := NFinstances}} -> S1#{instances => 'erlang_++'(PFinstances, NFinstances, TrUserData)};
        {_, #{instances := NFinstances}} -> S1#{instances => NFinstances};
        {#{instances := PFinstances}, _} -> S1#{instances => PFinstances};
        {_, _} -> S1
    end.

-compile({nowarn_unused_function,merge_msg_get_store_request/3}).
merge_msg_get_store_request(PMsg, NMsg, _) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {_, #{store_id := NFstore_id}} -> S1#{store_id => NFstore_id};
        {#{store_id := PFstore_id}, _} -> S1#{store_id => PFstore_id};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_get_store_response/3}).
merge_msg_get_store_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{instances := PFinstances}, #{instances := NFinstances}} -> S1#{instances => 'erlang_++'(PFinstances, NFinstances, TrUserData)};
        {_, #{instances := NFinstances}} -> S1#{instances => NFinstances};
        {#{instances := PFinstances}, _} -> S1#{instances => PFinstances};
        {_, _} -> S1
    end.

-compile({nowarn_unused_function,merge_msg_watch_stores_request/3}).
merge_msg_watch_stores_request(PMsg, NMsg, _) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {_, #{include_snapshot := NFinclude_snapshot}} -> S1#{include_snapshot => NFinclude_snapshot};
        {#{include_snapshot := PFinclude_snapshot}, _} -> S1#{include_snapshot => PFinclude_snapshot};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_store_event/3}).
merge_msg_store_event(PMsg, NMsg, TrUserData) ->
